#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto&x:a) scanf("%lld",&x);
        const long long NEG=-(1LL<<60), POS=(1LL<<60);
        vector<long long> pre(n), suf(n);
        vector<char> pok(n), sok(n);
        long long cur=NEG; bool ok=true;
        for(int i=0;i<n;i++){
            if(ok){
                if(a[i]>cur) cur=a[i];
                else if(a[i]+1>cur) cur=a[i]+1;
                else ok=false;
            }
            pok[i]=ok; pre[i]=cur;
        }
        cur=POS; ok=true;
        for(int i=n-1;i>=0;i--){
            if(ok){
                if(a[i]+1<cur) cur=a[i]+1;
                else if(a[i]<cur) cur=a[i];
                else ok=false;
            }
            sok[i]=ok; suf[i]=cur;
        }
        bool good=false;
        for(int r=0;r<n&&!good;r++){
            if(r>0&&!pok[r-1]) continue;
            if(r<n-1&&!sok[r+1]) continue;
            long long L=(r==0)?NEG:pre[r-1];
            long long R=(r==n-1)?POS:suf[r+1];
            if(L<R) good=true;
        }
        puts(good?"YES":"NO");
    }
}

