int main(){
    string s,t; cin>>s>>t;
    int n=s.size();
    int ct[26]={0}, cs[26]={0};
    for(char c:t) ct[c-'A']++;
    for(char c:s) cs[c-'A']++;
    int M=0;
    for(int x=0;x<26;x++) M+=min(cs[x],ct[x]);
    printf("%d\n", n-M);
    string u;
    for(int i=0;i<n;i++){
        cs[s[i]-'A']--;
        for(int c=0;c<26;c++){
            if(!ct[c]) continue;
            ct[c]--;
            int g=(c==s[i]-'A');
            int tot=0;
            for(int x=0;x<26;x++) tot+=min(cs[x],ct[x]);
            if(tot==M-g){ u+=char('A'+c); M-=g; break; }
            ct[c]++;
        }
    }
    printf("%s\n",u.c_str());
}

