typedef long long ll;
int n,m; ll a;
vector<ll> b,p;
bool check(int r, ll &pers){
    ll sp=0,cap=0;
    for(int i=0;i<r;i++){ sp+=p[i]; cap+=min(b[n-r+i],p[i]); }
    ll need=max(0LL,sp-a);
    pers=need;
    return cap>=need;
}
int main(){
    scanf("%d %d %lld",&n,&m,&a);
