#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<int> a(n+1), pos(n+1);
    for(int i=1;i<=n;i++){ scanf("%d",&a[i]); pos[a[i]]=i; }
    vector<char> comp(n+2,0); comp[0]=comp[1]=1;
    for(int i=2;i<=n+1;i++) if(!comp[i]) for(long long j=(long long)i*i;j<=n+1;j+=i) comp[j]=1;
    vector<pair<int,int>> ops;
    for(int i=1;i<=n;i++){
        int p=pos[i];
        while(p!=i){
            int d=p-i+1, q=d;
            while(comp[q]) q--;
            int l=p-q+1;
            int vl=a[l], vp=a[p];
            swap(a[l],a[p]); pos[vp]=l; pos[vl]=p;
            ops.push_back({l,p});
            p=l;
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto [x,y]:ops) printf("%d %d\n",x,y);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m,k,w; cin>>n>>m>>k>>w;
    vector<vector<string>> g(k, vector<string>(n));
    for(auto&L:g) for(auto&r:L) cin>>r;
    long long full=(long long)n*m;
    vector<long long> dist(k,full);
    vector<int> par(k,-1);
    vector<char> in(k,0);
    vector<int> order; long long total=0;
    for(int it=0;it<k;it++){
        int u=-1;
        for(int i=0;i<k;i++) if(!in[i]&&(u<0||dist[i]<dist[u])) u=i;
        in[u]=1; total+=dist[u]; order.push_back(u);
        for(int v=0;v<k;v++) if(!in[v]){
            int d=0;
            for(int r=0;r<n;r++) for(int c=0;c<m;c++) d+=g[u][r][c]!=g[v][r][c];
            long long cost=(long long)d*w;
            if(cost<dist[v]){ dist[v]=cost; par[v]=u; }
        }
    }
    printf("%lld\n",total);
    for(int u:order) printf("%d %d\n",u+1,par[u]<0?0:par[u]+1);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<long long> x(n);
    for(auto&v:x) scanf("%lld",&v);
    sort(x.begin(),x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    int u=x.size();
    auto cover=[&](long long D, vector<long long>* starts)->bool{
        int cnt=0, i=0;
        while(i<u){
            long long s=x[i];
            if(starts) starts->push_back(s);
            cnt++;
            i=upper_bound(x.begin(),x.end(),s+D)-x.begin();
        }
        return cnt<=3;
    };
    long long lo=0, hi=2000000000LL;
    while(lo<hi){ long long mid=(lo+hi)/2; if(cover(mid,nullptr)) hi=mid; else lo=mid+1; }
    vector<long long> st; cover(lo,&st);
    while(st.size()<3) st.push_back(st.back());
    printf("%.6f\n", lo/2.0);
    printf("%.6f %.6f %.6f\n", st[0]+lo/2.0, st[1]+lo/2.0, st[2]+lo/2.0);
}

