int main(){
    int n; scanf("%d",&n);
    vector<vector<pair<int,int>>> adj(n+1);
    for(int i=1;i<n;i++){
        int u,v; scanf("%d %d",&u,&v);
        adj[u].push_back({v,i}); adj[v].push_back({u,i});
    }
    int D=0;
    for(int u=1;u<=n;u++) D=max(D,(int)adj[u].size());
    vector<int> pc(n+1,0), par(n+1,0), ecol(n,0);
    vector<int> q={1};
    for(size_t h=0;h<q.size();h++){
        int u=q[h], c=1;
        for(auto [v,e]:adj[u]){
            if(v==par[u]) continue;
            if(c==pc[u]) c++;
            ecol[e]=c; pc[v]=c; par[v]=u; q.push_back(v); c++;
        }
    }
    vector<vector<int>> day(D+1);
    for(int e=1;e<n;e++) day[ecol[e]].push_back(e);
    printf("%d\n",D);
    for(int d=1;d<=D;d++){
        printf("%d",(int)day[d].size());
        for(int e:day[d]) printf(" %d",e);
        printf("\n");
    }
}

