#include <bits/stdc++.h>
using namespace std;
int main(){
    vector<string> tk; string w;
    while(cin>>w) tk.push_back(w);
    long long n=stoll(tk.back());
    int L=tk.size();
    vector<int> sg; sg.push_back(1);
    for(int i=1;i<=L-4;i+=2) sg.push_back(tk[i]=="+"?1:-1);
    long long P=0,Mn=0;
    for(int s:sg) { if(s>0) P++; else Mn++; }
    if(n<P-Mn*n || n>P*n-Mn){ puts("Impossible"); return 0; }
    vector<long long> v(sg.size(),1);
    long long extra=n-(P-Mn);
    for(size_t i=0;i<sg.size()&&extra!=0;i++){
        if(extra>0&&sg[i]>0){ long long add=min(extra,n-1); v[i]+=add; extra-=add; }
        else if(extra<0&&sg[i]<0){ long long add=min(-extra,n-1); v[i]+=add; extra+=add; }
    }
    puts("Possible");
    for(size_t i=0;i<v.size();i++){
        if(i>0) printf(" %c ", sg[i]>0?'+':'-');
        printf("%lld", v[i]);
    }
    printf(" = %lld\n", n);
}

