#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll gcdll(ll a,ll b){ return b?gcdll(b,a%b):a; }
ll egcd(ll a,ll b,ll&x,ll&y){ if(!b){x=1;y=0;return a;} ll x1,y1; ll g=egcd(b,a%b,x1,y1); x=y1; y=x1-(a/b)*y1; return g; }
int main(){
    ll n,m; int k; scanf("%lld %lld %d",&n,&m,&k);
    ll A=2*n, B=2*m, g=gcdll(A,B), L=A/g*B, m1=B/g, n1=A/g;
    ll xi,yi; egcd(n1%m1,m1,xi,yi); ll inv=((xi%m1)+m1)%m1;
    ll lcmNM=n/gcdll(n,m)*m;
    while(k--){
        ll x,y; scanf("%lld %lld",&x,&y);
        ll as[2]={x,A-x}, bs[2]={y,B-y}, best=-1;
        for(ll a:as) for(ll b:bs){
            ll d=b-a;
            if(((d%g)+g)%g!=0) continue;
            ll kk=((((d/g)%m1)+m1)%m1)*inv%m1;
            ll t=((a+A*kk)%L+L)%L;
            if(t==0) t=L;
            if(best<0||t<best) best=t;
        }
        printf("%lld\n",(best>=0&&best<lcmNM)?best:-1LL);
    }
}

#include <bits/stdc++.h>
using namespace std;
const char* nm[6]={"S","M","L","XL","XXL","XXXL"};
int idOf(const string&x){ for(int j=0;j<6;j++) if(x==nm[j]) return j; return -1; }
int main(){
    long long st[6];
    for(int i=0;i<6;i++) scanf("%lld",&st[i]);
    int n; scanf("%d",&n);
    vector<vector<int>> sIdx(6), pIdx(5);
    for(int i=0;i<n;i++){
        char buf[32]; scanf("%31s",buf);
        string s=buf; size_t c=s.find(',');
        if(c==string::npos) sIdx[idOf(s)].push_back(i);
        else{ int a=idOf(s.substr(0,c)), b=idOf(s.substr(c+1)); pIdx[min(a,b)].push_back(i); }
    }
    vector<int> ans(n,0);
    for(int i=0;i<6;i++){
        if(st[i]<(long long)sIdx[i].size()){ puts("NO"); return 0; }
        for(int p:sIdx[i]) ans[p]=i;
        st[i]-=sIdx[i].size();
        if(i<5){
            auto&v=pIdx[i]; long long tot=v.size();
            long long left=min(st[i],tot);
            for(long long t=0;t<tot;t++) ans[v[t]]=(t<left)?i:i+1;
            st[i]-=left;
            long long rem=tot-left;
            if(rem>st[i+1]){ puts("NO"); return 0; }
            st[i+1]-=rem;
        }
    }
    puts("YES");
    for(int i=0;i<n;i++) printf("%s\n",nm[ans[i]]);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    if(n==1){ puts("1=1"); return 0; }
    const int N=10000;
    vector<int> pr; vector<char> comp(N+1,0);
    for(int i=2;i<=N;i++) if(!comp[i]){ pr.push_back(i); for(int j=2*i;j<=N;j+=i) comp[j]=1; }
    int P=pr.size();
    vector<vector<char>> R(P+1, vector<char>(N+1,0));
    R[0][0]=1; R[0][1]=1;
    for(int i=0;i<P;i++){
        R[i+1]=R[i];
        for(int s=0;s+pr[i]<=N;s++) if(R[i][s]) R[i+1][s+pr[i]]=1;
    }
    if(!comp[n]){ printf("%d=%d\n",n,n); return 0; }
    int lim=upper_bound(pr.begin(),pr.end(),n)-pr.begin();
    if(!R[lim][n]){ puts("0"); return 0; }
    vector<int> terms; int r=n;
    while(r>1){
        int i=lim-1;
        while(i>=0&&!(pr[i]<=r&&R[i][r-pr[i]])) i--;
        if(i<0){ puts("0"); return 0; }
        terms.push_back(pr[i]); r-=pr[i]; lim=i;
    }
    if(r==1) terms.push_back(1);
    for(size_t i=0;i<terms.size();i++) printf("%s%d", i?"+":"", terms[i]);
    printf("=%d\n",n);
}
